struct Box<T> { var item: T }
extension Box: Equatable
    where T: Equatable {}
print(Box(item: 1) == Box(item: 1))

func sum(_ n: some Collection<Int>) -> Int {
    n.reduce(0, +)
}
print(sum([1, 2, 3]))
print(sum(Set([4, 5])))

func show<each T>(_ v: repeat each T) {
    for x in repeat each v { print(x) }
}
show(1, "two", true)

